'use strict';
const E=RPG,$=id=>document.getElementById(id),c=$('world'),g=c.getContext('2d');let s=E.fresh(),mode='explore',moving=false,cam={x:0,y:0};const T=16,VW=16,VH=14;let selected='yuris',cursor=null;let spellRange=5;
try{const saved=JSON.parse(localStorage.getItem(E.KEY));if(E.valid(saved))s=saved}catch{};
function prepareState(){E.normalize(s);s.equipment??={yuris:'短剣',ed:'長剣',celes:'杖'};s.dropped??=[];s.topics??=[];s.seen??={}}prepareState();
function save(){try{localStorage.setItem(E.KEY,JSON.stringify(s));return true}catch{E.say(s,'保存できません。ブラウザの保存許可を確認してください。');return false}}
function log(t){E.say(s,t);render()}function modal(title,text,choices=[]){$('commandmenu').hidden=true;$('mt').textContent=title;$('mb').innerHTML='';for(const p of text.split('\n')){let el=document.createElement('p');el.textContent=p;$('mb').append(el)}$('choices').replaceChildren();for(const [label,fn]of choices){let b=document.createElement('button');b.textContent=label;b.onclick=()=>{fn();render();save()};$('choices').append(b)}if(!$('modal').open)$('modal').show()}
function close(){$('modal').close();$('modal').classList.remove('conversation');render();save()}
$('modal').querySelector('.close').onclick=close;
const story={ed:{intro:'「町の外で、壊れた守護機霊が動いている。剣だけで解決する話ではなさそうだ」',name:'エド。身分よりも、この旅で何ができるかを見てほしい。',town:'東の橋を渡れば森。その先の古い遺跡から、昨夜も光が漏れていた。',join:'君が聴く声の行く先を、僕も見届けたい。'},celes:{intro:'「霊流が不規則に脈打っている。古い機霊は敵ではなく、何かを守っているのかもしれない」',name:'セレス。封印と、古い文明の言葉を学んでいる。',town:'森の古箱に調律片が残っているはず。機霊に示せば戦わずに話せるかもしれない。',join:'ええ。危険な封印に一人で触れさせるわけにはいかないもの。'},smith:{intro:'「あの霊灯が消えてから、旅人が道に迷う。部品か木材があれば直せるんだが」',name:'オルだ。この町のものは、だいたい俺の槌が一度は触っている。',town:'資材箱の木を使っていい。霊灯は部品一つか、木材二つで仮修理できる。'},inn:{intro:'「いらっしゃい。腹を満たしてから出かけるんだよ」',name:'ここでは宿の主人で十分さ。旅の話が何より好きでね。',town:'東の海辺に霊晶が落ちている。南の焚き火も安全な休憩場所になるよ。'},keeper:{intro:'《この門は侵入を拒むのではない。霊流の破裂から町を守っている》',name:'《名は失われた。記録の番人と呼べ》',town:'《中央の霊核は傷ついている。霊晶一つを接続すれば、鎮められる》'}};
const topics={
ed:[['仕事','剣の稽古はした。でも、誰を守るのかは旅で覚えたい。機霊を斬る前に、声を聴いてみよう。'],['守護機霊','以前は旅人を案内していたそうだ。人を襲うようになったのは、霊灯が消えた晩から。'],['町の外','東の橋の先は森だ。足並みをそろえよう。戦う時は狭い道より、開けた場所がいい。']],
celes:[['仕事','古い文字の意味を調べている。同じ印でも、人は「封印」、機霊は「約束」と読むらしい。'],['調律片','森の北に残された古箱にある。扉の鍵にも、機霊に身を示す印にもなる。'],['封印','私が一緒なら門の文字を読める。けれど、扉の奥の機霊まで止められるわけではない。'],['ノア','あなたには、あの声が聞こえるのね。私にはまだ、かすかな旋律にしか聞こえない。']],
smith:[['仕事','直して使えるものを、すぐ捨てるのが嫌いでね。この町の暮らしをつなぐのが俺の仕事だ。'],['霊灯','芯を支える留め具だ。宿の古い部品を借りるか、ここの木材を二つ使って補強すればいい。'],['機霊','昔は壊れた車輪まで運んでくれた。奴らを敵と呼ぶには、俺は世話になりすぎた。']],
inn:[['仕事','食事と、帰る場所を用意する。それだけでも旅には必要だろう？'],['うわさ','海辺で、光る石を拾った旅人がいた。東の南岸だよ。'],['町の人','オルは口が悪いが、困っている者を追い返せない。エドも似てきたね。']],
keeper:[['役目','《霊流が町へ溢れることを防ぐ。保護対象は、人だけではない》'],['暴走','《命令は残った。だが、命令を与えた者は戻らない。判断を、誰に問えばよかった》'],['霊核','《中心の亀裂に、澄んだ霊晶を接続せよ。森にも海辺にも、同じ波長の石がある》']]};
function remember(n,topic,text){const id=n.id+':'+topic;if(!s.topics.some(t=>t.id===id))s.topics.push({id,title:n.name+' / '+topic,text})}
function talk(n){const d=story[n.id];const reply=(topic,text)=>{remember(n,topic,text);modal(n.name+' / '+topic,text,[['話を続ける',()=>talk(n)]])};const choices=[['名前',()=>reply('名前',d.name)],['この土地',()=>reply('この土地',d.town)],...topics[n.id].filter(([topic])=>['仕事','うわさ'].includes(topic)||d.intro.includes(topic)||s.topics.some(a=>a.text.includes(topic))).map(([topic,text])=>[topic,()=>reply(topic,text)])];if(['ed','celes'].includes(n.id)&&!s.party.some(p=>p.id===n.id))choices.push(['一緒に来て',()=>{E.recruit(s,n.id);modal(n.name,d.join,[['旅を続ける',close]])}]);if(n.id==='inn')choices.push(['食料を買う（3枚）',()=>{if(s.gold>=3){s.gold-=3;s.food+=3;modal(n.name,'食料を3つ受け取った。',[['戻る',()=>talk(n)]])}else modal(n.name,'お金が足りないね。',[['戻る',()=>talk(n)]])}],['部品を借りる',()=>{if(!s.flags.borrowed){s.parts++;s.flags.borrowed=true;E.say(s,'宿から霊灯の部品を借りた。')}modal(n.name,'霊灯のためなら持っていっておくれ。',[['戻る',()=>talk(n)]])}]);choices.push(['別れる',close]);let intro=d.intro;if(E.isNight?.(s)&&n.id!=='keeper')intro='「もう夜か。明日の支度をしていたところだよ」\n'+intro;if(s.flags.ending)intro=n.id==='keeper'?'《静かだ。守るべき町の音が、ようやく聞こえる》':'「森が静かになった。君たちが何をしたか、話してくれないか」';else if(s.flags.lamp&&['smith','inn'].includes(n.id))intro='「霊灯が戻ったね。ありがとう。けれど森の声は、まだ止まらないようだ」';modal(n.name,intro,choices)}
function inspect(o){if(s.combat?.active){log('戦闘中は調査・拾得・物の使用はできない。まず安全を確保しよう。');return}if(o.key){modal(o.name,'地面に置かれた'+o.name+'。',[['拾う',()=>{s[o.key]++;s.dropped=s.dropped.filter(a=>a.id!==o.id);close()}],['そのまま',close]]);return}if(o.desc){modal(o.name,o.desc,[['閉じる',close]]);return}const back=[['閉じる',close]];switch(o.id){case'sign':modal('広場の掲示板','【町からのお知らせ】\n東の霊灯が消えています。修理できる旅人は工房へ。\n【森の道】\n橋の先は獣に注意。仲間と食料を忘れずに。\n【ひびき読み】\n遺跡の機霊の声を聴ける人を探しています。',back);break;
case'crate':s.wood+=2;s.opened.push(o.id);modal(o.name,'鍛冶師の許可した木材を2つ拾った。',back);break;
case'well':modal(o.name,'冷たい水を汲んだ。仲間全員の体力が少し戻る。',back);s.party.forEach(p=>p.hp=Math.min(p.max,p.hp+8));break;
case'lamp':if(s.flags.lamp){modal('修復した霊灯','温かな光が道を照らしている。人々はこの灯りを頼りに帰ってくる。',back);break}modal(o.name,'霊灯の芯を支える留め具が壊れている。',[['部品を使う',()=>repair('parts',1)],['木材で直す',()=>repair('wood',2)],...back]);break;
case'herb1':case'herb2':s.herbs+=2;s.opened.push(o.id);modal('薬草を拾った','薬草が2つ増えた。持ち物から使える。',back);break;
case'cache':s.keys=1;s.crystal++;s.opened.push(o.id);modal(o.name,'調律片と霊晶を手に入れた。調律片は遺跡の門を開けられそうだ。',back);break;
case'gate':if(s.flags.gate){modal('開いた門','奥で古い機霊が待っている。',back);break}modal(o.name,'扉に、調律片を差し込むくぼみがある。セレスなら封印を解けるかもしれない。',[['調律片を使う',()=>{if(!s.keys)return modal('門','森の古箱にある調律片が必要だ。',back);openGate()}],['セレスに頼む',()=>{if(!s.party.some(p=>p.id==='celes'))return modal('門','セレスが仲間にいない。町の北の建物で話してみよう。',back);openGate()}],...back]);break;
case'crystal':s.crystal+=2;s.opened.push(o.id);modal(o.name,'海風に磨かれた霊晶を2つ手に入れた。',back);break;
case'camp':modal('旅人の焚き火','火のそばで一息つける。食料1つで全回復。',[['休む',()=>{E.rest(s);close()}],...back]);break;
case'altar':if(s.flags.ending){modal('静まった霊流','機霊の鼓動が穏やかに続いている。町へ戻っても、探索を続けてもいい。',back);break}modal('霊流の中枢','ノアの声が響く。《壊れたのではない。長い間、独りで守り続けていたんだ》\n霊晶を接続すれば、暴走を鎮められる。',[['霊晶を接続する',()=>{if(!s.crystal)return modal('中枢','霊晶が必要だ。海辺や森で探そう。',back);s.crystal--;s.flags.ending=true;s.gold+=15;s.enemies.filter(e=>e.id==='sentinel').forEach(e=>e.hp=0);modal('第一章・霊流の旅人','霊流が整い、機霊は静かに頭を下げた。\n《ありがとう。今度は、私が君たちの帰る道を照らそう》\n東の石橋の先には、村・修道院・港がある。灯台に残る三つの記憶を追い、旅は続いていく。',back)}],...back]);break}}
function repair(item,n){if(s[item]<n){modal('霊灯の修理',item==='parts'?'宿で部品を借りられそうだ。':'工房の資材箱に木材がある。',[['戻る',()=>inspect(E.objs.find(o=>o.id==='lamp'))]]);return}s[item]-=n;s.flags.lamp=item;s.gold+=8;E.say(s,'霊灯がともった。町から謝礼8枚。');modal('霊灯に光が戻る','足元を温かい光が包む。戦わずに町を助けることができた。',[['続ける',close]])}
function openGate(){s.flags.gate=true;modal('門が開いた','刻まれた紋様が光り、古い扉が開いた。',[['続ける',close]])}
function interaction(x,y){const from=s.combat?.active?E.position(s,s.party.find(p=>p.id===selected)||s.party[0]):s;if(E.visible&&!E.visible(s,from,{x,y})){log('壁や木に遮られて見えない。近づくか扉を開こう。');return}const e=E.enemy(s,x,y);if(e){if(!s.combat?.active&&mode==='explore'&&e.type==='golem'&&E.distance(s,e)<=4){modal('守護機霊','《侵入者……保護対象……判定できない》',[['調律片を示す',()=>{if(!s.keys){modal('守護機霊','声はまだ届かない。調律片が必要だ。',[['閉じる',close]]);return}e.hp=0;s.flags.pacified=true;E.say(s,'守護機霊を調律し、戦いを避けた。');close()}],['戦う',()=>{mode='fight';close()}],['離れる',close]]);return}if(!E.attack(s,e,mode==='magic',selected))log('装備した武器の射程は'+Gear.stats(s.party.find(p=>p.id===selected)||s.party[0]).range+'マス。射線と矢の残りも確認しよう。');render();save();return}const n=E.npc(s,x,y),o=s.dropped.find(o=>o.x===x&&o.y===y)||E.obj(s,x,y);
if(mode==='talk'&&!n){log('そこに話せる相手はいない。');return}
if(E.terrain(x,y)==='door'){if(E.distance(s,{x,y})>1){walkNear(x,y,()=>interaction(x,y));return}E.toggleDoor(s,x,y);render();save();return}
if(mode==='look'&&!n&&!o){log({grass:'草が風に揺れている。',tree:'枝葉の重なる木々。通り抜けられない。',water:'冷たい水が流れている。',road:'旅人の足跡が残る道。',wall:'厚い石の壁。'}[E.terrain(x,y)]||'床石を調べた。何も見つからない。');return}
if(n||o){if(E.distance(s,{x,y})>1){walkNear(x,y,()=>interaction(x,y));return}if(n){if(s.combat?.active){log('今は戦いに集中しよう。');return}talk(n);}else inspect(o);render();save();return}if(mode!=='explore'){log('敵を選んでください。移動は「歩く・調べる」。');return}walkTo(x,y)}
function walkNear(x,y,done){let routes=[[1,0],[-1,0],[0,1],[0,-1]].map(([a,b])=>E.travelPath(s,x+a,y+b)).filter(p=>p.length).sort((a,b)=>a.length-b.length);if(!routes.length){log('そこへ近づく道が見つからない。');return}walkRoute(routes[0],done)}
function walkTo(x,y){const p=E.travelPath(s,x,y);if(!p.length){log('そこへは歩けない。');return}walkRoute(p)}
function walkRoute(p,done){if(moving)return;moving=true;let i=0;function step(){if($('modal').open||s.combat.active||i>=p.length){moving=false;if(!s.combat.active&&i>=p.length&&done)done();return}let [x,y]=p[i++];if(E.terrain(x,y)==='door'&&!s.openedDoors[`${x},${y}`]){E.toggleDoor(s,x,y);i--;}else if(!E.move(s,x-s.x,y-s.y)){moving=false;return}render();save();if(s.combat.active||s.enemies.some(e=>e.hp>0&&E.distance(s,e)<=2)){moving=false;log('敵を発見。仲間を選び、攻撃・移動・待機で行動しよう。');return}setTimeout(step,70)}step()}
function canSee(x,y){const p=s.party.find(p=>p.id===selected)||s.party[0];return E.inSight(s,s.combat.active?E.position(s,p):s,{x,y})}
function draw(){const active=s.party.find(p=>p.id===selected)||s.party[0],focus=s.combat?.active?E.position(s,active):s;cam.x=Math.max(0,Math.min(E.W-VW,focus.x-8));cam.y=Math.max(0,Math.min(E.H-VH,focus.y-7));g.imageSmoothingEnabled=false;g.clearRect(0,0,c.width,c.height);for(let y=0;y<VH;y++)for(let x=0;x<VW;x++){g.save();g.translate(x*T,y*T);const wx=x+cam.x,wy=y+cam.y;let terrain=E.terrain(wx,wy);Painter.tile(g,terrain,wx,wy);if(terrain==='door'&&s.openedDoors?.[`${wx},${wy}`]){g.fillStyle='#735838';g.fillRect(0,0,16,16);g.fillStyle='#32281f';g.fillRect(0,0,3,16)}if(canSee(wx,wy)){s.seen[wx+','+wy]=true}else{const indoor=E.World.buildings.some(b=>wx>=b.x&&wx<b.x+b.w&&wy>=b.y&&wy<b.y+b.h);g.fillStyle=indoor?'#080b13':'#10231b66';g.fillRect(0,0,T,T)}g.restore()}if(s.combat.active||mode==='fight'||mode==='magic'){const origin=E.position(s,active),range=mode==='magic'?spellRange:Gear.stats(active).range;for(let yy=0;yy<VH;yy++)for(let xx=0;xx<VW;xx++){const at={x:xx+cam.x,y:yy+cam.y};if(E.distance(origin,at)>0&&E.distance(origin,at)<=range&&E.visible(s,origin,at)){g.fillStyle=mode==='magic'?'#83a6f21c':'#efcd8020';g.fillRect(xx*T,yy*T,T,T)}}}for(const o of [...E.objs.map(o=>s.moved[o.id]?{...o,...s.moved[o.id]}:o),...s.dropped])if(!s.opened.includes(o.id)&&canSee(o.x,o.y)){g.save();g.translate((o.x-cam.x)*T,(o.y-cam.y)*T);Painter.object(g,o.type,s);g.restore()}let entities=[...(E.people?E.people(s):E.npcs).filter(n=>!s.party.some(p=>p.id===n.id)),...s.enemies.filter(e=>e.hp>0).map(e=>({...e,color:'#879997',kind:e.type})),...s.party.map(p=>({...p,...E.position(s,p),color:p.id==='yuris'?'#468d9f':p.id==='ed'?'#b8893c':'#9580bd'}))].sort((a,b)=>a.y-b.y);for(const o of entities){if(!canSee(o.x,o.y))continue;g.save();g.translate((o.x-cam.x)*T,(o.y-cam.y)*T);Painter.sprite(g,o.color,o.kind||'person',o.id,s.turn,o.hp);if(o.gear)Painter.held(g,Gear.items[o.gear.weapon]?.icon,!!o.gear.shield);if(o.kind&&Number.isFinite(o.hp)){g.fillStyle='#342b2b';g.fillRect(2,0,12,2);g.fillStyle='#cf9670';g.fillRect(2,0,Math.ceil(o.hp/o.max*12),1)}if(o.sleep>0){g.fillStyle='#d4d7ff';g.font='7px monospace';g.fillText('z',10,1)}if(o.hp===0){g.fillStyle='#931b1baa';g.fillRect(0,9,16,7)}g.restore()}for(const b of E.World.buildings){if(s.x>=b.x&&s.x<b.x+b.w&&s.y>=b.y&&s.y<b.y+b.h)continue;if(b.x+b.w<cam.x||b.x>cam.x+VW||b.y+b.h<cam.y||b.y>cam.y+VH)continue;g.save();g.translate((b.x-cam.x)*T,(b.y-cam.y)*T);Painter.roof(g,b,s);g.restore()}const pos=E.position(s,active);g.strokeStyle='#f4e4a3';g.lineWidth=1;g.strokeRect((pos.x-cam.x)*T+.5,(pos.y-cam.y)*T+.5,15,15);if(cursor){g.strokeStyle='#fff';g.strokeRect((cursor.x-cam.x)*T-.5,(cursor.y-cam.y)*T-.5,17,17)}if((E.isNight?E.isNight(s):s.turn%80>=55)){g.fillStyle='#10274744';g.fillRect(0,0,c.width,c.height)}}
function render(){prepareState();E.detectCombat(s);if(s.combat.ended){if(mode==='fight'||mode==='magic')mode='explore';selected=s.party[0].id;cursor=null;$('targethint').hidden=true;delete s.combat.ended;}if(s.combat?.active&&mode==='explore')mode='fight';if(s.combat?.active&&!E.canAct(s,selected))selected=E.nextActor(s)||selected;if(s.combat?.active)$('hint').textContent=(s.party.find(p=>p.id===selected)?.name||'仲間')+'の番 ／ 矢印で個別移動・敵を選んで攻撃・待機で次へ';draw();$('place').textContent=s.x>31&&s.y<13?'忘れられた霊堂':s.x>21?'東の森と海辺':'ノルヴィクの町';$('clock').textContent=(s.combat?.active?'戦闘 '+s.combat.round+'巡 · ':'')+`${(E.isNight?E.isNight(s):s.turn%80>=55)?'☾ 夜':'☀ 昼'} · 金 ${s.gold} · 食料 ${s.food}`;$('party').replaceChildren();s.party.forEach(p=>{let d=document.createElement('div');d.className='member'+(p.id===selected?' selected':'');d.tabIndex=0;d.setAttribute('role','button');d.onclick=()=>{selected=p.id;render()};d.onkeydown=e=>{if(e.key==='Enter'){selected=p.id;render()}};let a=document.createElement('strong');a.textContent=p.name+(p.hp<=0?' 戦闘不能':s.combat?.active?(s.combat.acted.includes(p.id)?' 済':' 待'):'');let sm=document.createElement('small');sm.textContent=`HP ${p.hp}/${p.max}`;let b=document.createElement('div');b.className='bar';let i=document.createElement('i');i.style.width=(p.hp/p.max*100)+'%';b.append(i);let role=document.createElement('div');role.textContent=(s.equipment[p.id]||p.role)+` · MP ${p.mp||0}`;role.style.fontSize='12px';d.append(a,sm,b,role);$('party').append(d)});$('quest').textContent=s.flags.ending?'東の街道の先にも、人と機霊の声がある。':s.flags.gate?'霊堂の奥で、機霊の声を聴く。':s.flags.lamp?'仲間と東の森へ。調律片で霊堂の門を開く。':'町で仲間を誘い、霊灯を修理しよう。';$('log').replaceChildren();s.log.slice(0,8).forEach(t=>{let d=document.createElement('div');d.className='logline';d.textContent=t;$('log').append(d)});for(let id of ['explore','talk','look','fight','magic'])$(id).classList.toggle('active',mode===id)}
function chooseMode(id){if(id==='explore'&&s.combat?.active&&!E.endCombat(s)){mode='fight';$('commandmenu').hidden=true;log('まだ敵が近い。各人を動かして距離を取れば戦闘を抜けられる。');return}mode=id;cursor=['talk','look'].includes(id)?{x:s.x,y:s.y-1}:null;$('commandmenu').hidden=true;$('targethint').hidden=id==='explore';$('targethint').textContent={talk:'話す相手を選ぶ',look:'調べる場所を選ぶ',fight:'仲間を選び、敵を選ぶ',magic:'術者を選び、敵を選ぶ'}[id]||'';$('hint').textContent=id==='explore'?'方向キーで歩く ／ Aでコマンド ／ 地図をタップでも移動':$('targethint').textContent;render()}
c.onclick=ev=>{if(moving||$('modal').open)return;const r=c.getBoundingClientRect();const x=Math.floor((ev.clientX-r.left)*c.width/r.width/T)+cam.x,y=Math.floor((ev.clientY-r.top)*c.height/r.height/T)+cam.y;cursor={x,y};$('commandmenu').hidden=true;interaction(x,y)};
for(const id of ['explore','talk','look','fight','magic'])$(id).onclick=()=>chooseMode(id);
$('menu').onclick=()=>{if(cursor&&['talk','look'].includes(mode)){interaction(cursor.x,cursor.y);return}$('commandmenu').hidden=!$('commandmenu').hidden;if(!$('commandmenu').hidden)$('commandmenu').querySelector('button').focus()};$('cancel').onclick=()=>{if($('modal').open)close();chooseMode('explore')};
$('wait').onclick=()=>{if(s.combat?.active)E.waitActor(s,selected);else E.tick(s);render();save()};$('rest').onclick=()=>{E.rest(s);$('commandmenu').hidden=true;render();save()};$('save').onclick=()=>{if(save())log('旅の記録を保存した。');$('commandmenu').hidden=true};
function bag(){const items=[['薬草','herbs',s.herbs],['食料','food',s.food],['霊晶','crystal',s.crystal],['部品','parts',s.parts],['木材','wood',s.wood],['調律片','keys',s.keys]];modal('道具 / '+(s.party.find(p=>p.id===selected)?.name||'ユリス'),`金貨 ${s.gold} ／ 装備 ${s.equipment[selected]||'なし'}\n共有の荷物。選んで使う・地面に置く。`,[['装備を確認',()=>equipment()],['戻る',close]]);let grid=document.createElement('div');grid.className='inventory';for(const [name,key,qty] of items){let b=document.createElement('button');b.textContent=name+' ×'+qty;b.disabled=!qty;b.onclick=()=>{if(s.combat?.active){modal(name,'戦闘中は道具の整理はできない。',[['戻る',bag]]);return}modal(name,`${name}をどうする？`,[['使う',()=>{if(key==='herbs'){E.heal(s);close()}else if(key==='food'){E.rest(s);close()}else {close();chooseMode('look');log('使いたい対象を「調べる」で選ぶ。')}}],['地面に置く',()=>{s[key]--;s.dropped.push({id:'drop'+Date.now(),x:s.x,y:s.y,type:key==='crystal'?'crystal':'chest',name,key});E.say(s,name+'を足元に置いた。');close()}],['戻る',bag]])};grid.append(b)}$('mb').append(grid)}
function equipment(){if(s.combat?.active){modal('装備','戦闘中は装備を変更できない。',[['戻る',bag]]);return}const p=s.party.find(p=>p.id===selected);modal(p.name+'の装備',`武器：${s.equipment[p.id]||'素手'}\n攻撃力：${p.atk} ／ 体力：${p.hp}/${p.max}\n霊力：${p.mp||0} ／ ${p.id==='ed'?'霊術なし':'霊光（MP3、射程4）'}\n装備を外すと攻撃力が下がる。`,[['武器を持つ / 外す',()=>{if(s.equipment[p.id]){s.equipment[p.id]='';p.atk=2}else{s.equipment[p.id]=p.id==='ed'?'長剣':p.id==='celes'?'杖':'短剣';p.atk=p.id==='ed'?7:p.id==='celes'?4:8}equipment();save();render()}],['道具へ',bag]])}
$('bag').onclick=()=>{$('commandmenu').hidden=true;bag()};
$('formation').onclick=()=>{modal('隊列 / 操作する仲間','選んだ仲間が戦闘時の操作対象になる。通常歩行ではユリスに続く。',s.party.map(p=>[p.name,()=>{selected=p.id;close();log(p.name+'を選択。戦闘中はこの仲間を個別に動かせる。戦闘外では全員がユリスに続く。')}]).concat([['後衛の順番を入れ替える',()=>{if(s.party.length>2){[s.party[1],s.party[2]]=[s.party[2],s.party[1]]}close()}],['閉じる',close]]))};
$('journal').onclick=()=>modal('旅の手帳',s.topics.length?s.topics.map(a=>a.title+'\n'+a.text).join('\n\n'):'まだ聞き書きはない。町の人に話しかけ、仕事や噂を聞いてみよう。\n東の霊灯が消え、森から不思議な声がする。',[['閉じる',close]]);
$('map').onclick=()=>{modal('ノルヴィク周辺図','左：町。中央：橋。右上：霊堂。右下：海辺。', [['閉じる',close]]);let cv=document.createElement('canvas');cv.width=440;cv.height=360;cv.className='mapcanvas';let ctx=cv.getContext('2d');for(let y=0;y<E.H;y++)for(let x=0;x<E.W;x++){ctx.fillStyle={grass:'#466c48',water:'#285b72',road:'#a58d62',wall:'#c1bda6',tree:'#284b32',floor:'#755d42',door:'#b39a60',stone:'#77837b'}[E.terrain(x,y)];ctx.fillRect(x*10,y*10,10,10)}ctx.fillStyle='#fff';ctx.fillRect(s.x*10,s.y*10,10,10);$('mb').append(cv)};
$('help').onclick=()=>modal('霊流の旅人・遊び方','Aのコマンドから「話す」「調べる」を選び、地図の対象をタップ。地面をタップすると移動。閉じた扉は隣から調べて開けます。矢印キー／画面の矢印でも移動できます。\n戦闘は、生存している仲間全員が1回ずつ移動・攻撃・待機をした後に敵が1回動くラウンド制です。行動済みは「済」、未行動は「待」。「攻撃」は隣、「霊光」は4マス以内。仲間欄で一人を選ぶと、その仲間の位置から攻撃します。戦闘中は矢印で選択した一人だけを移動できます。戦闘外では仲間が自動でついてきます。\n日中は広場のエド、北の書斎のセレスに話しかけよう。住人は夜になると宿や寝床へ歩いて移動します。町の工房と宿を調べると霊灯を修理できます。東の森から霊堂へ進む小さな冒険です。\nセーブはこのブラウザ内に自動保存。既存ユリスRPGとは完全に別です。',[['冒険する',close],['最初から（確認）',()=>modal('最初から？','このゲームのセーブを消して始め直します。既存RPGのセーブには触れません。',[['始め直す',()=>{s=E.fresh();prepareState();selected='yuris';chooseMode('explore');close()}],['やめる',close]])]]);
function directional(dx,dy){if(moving||$('modal').open)return;if(!$('commandmenu').hidden){const buttons=Array.from($('commandmenu').querySelectorAll('button'));let index=buttons.indexOf(document.activeElement);index=(index+(dy||dx)+buttons.length)%buttons.length;buttons[index].focus();return}if(mode==='talk'||mode==='look'){cursor??={x:s.x,y:s.y};cursor.x=Math.max(0,Math.min(E.W-1,cursor.x+dx));cursor.y=Math.max(0,Math.min(E.H-1,cursor.y+dy));render();return}if(s.combat?.active){const actor=s.party.find(p=>p.id===selected),pos=E.position(s,actor),e=E.enemy(s,pos.x+dx,pos.y+dy);if(e)E.attack(s,e,mode==='magic',selected);else E.moveActor(s,selected,dx,dy)}else{const e=E.enemy(s,s.x+dx,s.y+dy);if(e){chooseMode('fight');log('戦闘態勢。仲間を選び、敵を攻撃する。')}else if(E.terrain(s.x+dx,s.y+dy)==='door'&&!s.openedDoors?.[`${s.x+dx},${s.y+dy}`])interaction(s.x+dx,s.y+dy);else if(E.npc(s,s.x+dx,s.y+dy)||E.obj(s,s.x+dx,s.y+dy)?.solid)interaction(s.x+dx,s.y+dy);else E.move(s,dx,dy)}render();save()}
document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>directional(...b.dataset.dir.split(',').map(Number)));document.addEventListener('keydown',ev=>{if(ev.repeat&&s.combat?.active){ev.preventDefault();return}let d={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]}[ev.key];if(d){ev.preventDefault();directional(...d)}if(ev.key==='Escape'||ev.key.toLowerCase()==='b')$('cancel').click();if((ev.key.toLowerCase()==='a'||ev.key==='Enter')&&!$('modal').open){ev.preventDefault();if(!$('commandmenu').hidden&&document.activeElement?.parentElement===$('commandmenu'))document.activeElement.click();else $('menu').click()}});chooseMode('explore');render();

$('sound').onclick=()=>{const on=GameAudio.toggle();$('sound').textContent='音 '+(on?'ON':'OFF');$('sound').setAttribute('aria-pressed',on)};
